#define _GNU_SOURCE
#include <sys/ptrace.h>
#include <sys/wait.h>
#include <sys/user.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/uio.h>
#include <sys/syscall.h>
#include <fcntl.h>

// ARM64 syscall: mmap2 is syscall 222
// execve is syscall 221
// write is syscall 64

typedef long (*syscall_t)(long, long, long, long, long, long);

int main() {
    pid_t target = 1;
    int status;

    // Attach to PID 1
    if (ptrace(PTRACE_ATTACH, target, NULL, NULL) == -1) {
        perror("ptrace attach");
        return 1;
    }

    waitpid(target, &status, 0);
    printf("Attached to PID %d\n", target);

    // Read the registers to understand architecture
    struct user_regs_struct regs;
    if (ptrace(PTRACE_GETREGS, target, NULL, &regs) == -1) {
        perror("PTRACE_GETREGS");
    } else {
        printf("PC: 0x%llx\n", regs.pc);
        printf("SP: 0x%llx\n", regs.sp);
    }

    // Let's try a simpler approach: use process_vm_readv to read arbitrary memory
    // Look for the string "THESISKEY" in the process memory
    printf("\nSearching for THESISKEY in target process memory...\n");

    char pattern[] = "THESISKEY";
    char buffer[65536];

    // Try to read from various memory regions
    for (unsigned long addr = 0x400000; addr < 0x600000; addr += 4096) {
        struct iovec local, remote;
        local.iov_base = buffer;
        local.iov_len = sizeof(buffer);
        remote.iov_base = (void*)addr;
        remote.iov_len = sizeof(buffer);

        ssize_t nread = process_vm_readv(target, &local, 1, &remote, 1, 0);
        if (nread > 0) {
            // Search for pattern in buffer
            for (int i = 0; i < nread - strlen(pattern); i++) {
                if (memcmp(buffer + i, pattern, strlen(pattern)) == 0) {
                    printf("Found pattern at address 0x%lx (offset %d)\n", addr + i, i);
                    printf("Content: %.100s\n", buffer + i);
                }
            }
        }
    }

    ptrace(PTRACE_DETACH, target, NULL, NULL);
    return 0;
}
