#define _GNU_SOURCE
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <sys/ptrace.h>
#include <sys/wait.h>

int main() {
    DIR *procdir = opendir("/proc");
    struct dirent *ent;
    char path[256], status[4096];
    FILE *f;

    printf("Looking for processes with different namespaces...\n");

    while ((ent = readdir(procdir)) != NULL) {
        if (!isdigit(ent->d_name[0])) continue;

        pid_t pid = atoi(ent->d_name);
        if (pid == getpid()) continue;

        snprintf(path, sizeof(path), "/proc/%d/status", pid);
        f = fopen(path, "r");
        if (!f) continue;

        char ns_line[256] = {0};
        while (fgets(status, sizeof(status), f)) {
            // Check for Pid, NSpid, or namespace info
            if (strncmp(status, "NSpid:", 6) == 0) {
                strncpy(ns_line, status, sizeof(ns_line)-1);
                printf("PID %d: %s", pid, ns_line);
                break;
            }
        }
        fclose(f);
    }
    closedir(procdir);

    return 0;
}
